def maximize_currency(N: int, A: List[int], exchanges: List[Tuple[int, int]]) -> int:
    for i in range(N-1):
        s = exchanges[i][0]
        t = exchanges[i][1]
        while A[i] >= s:
            temp = A[i] // s
            A[i] -= temp * s
            A[i+1] += temp * t
    return A[N-1]
